// Transparent recommendation prototype. No model calls or live trend claims.
const discovery={dismissed:new Set(),focusSkill:'AI literacy',campaigns:[]};
const skillPathways={
 'AI literacy':{why:'Learn to question AI outputs, write clear instructions and use AI responsibly.',steps:['Understand what AI can and cannot do','Practise a useful task and verify the result','Create a small project with a human review'],action:'AI literacy',roles:'Useful across learning, teaching and administration'},
 'Data literacy':{why:'Build confidence interpreting numbers, patterns and evidence before making a decision.',steps:['Read tables and charts','Practise with a simple spreadsheet','Explain one finding and its limitations'],action:'Data analysis',roles:'Explore in study, teaching and business decisions'},
 'Communication':{why:'Practise explaining ideas, asking questions and presenting your work clearly.',steps:['Set a speaking or writing goal','Practise with structured feedback','Share a short presentation or portfolio'],action:'Communication',roles:'Explore across education and work'},
 'Coding & computational thinking':{why:'Learn to break a problem into steps and build a small working solution.',steps:['Practise logic and problem decomposition','Choose an age-appropriate beginner tool','Build and explain a small project'],action:'Coding',roles:'Choose activities suited to the learner’s age and goals'},
 'Digital safety':{why:'Understand privacy, safe online behaviour and how to evaluate information.',steps:['Recognise common online risks','Practise source and privacy checks','Apply a safe-sharing checklist'],action:'Digital literacy',roles:'Explore safe habits for learning and work'}
};
const collegeExample={id:7,name:'Northstar College — Sample',initials:'NC',type:'Schools / Colleges',title:'Explore your next course',subtitle:'College · Undergraduate programmes',desc:'Compare programmes, campus facilities and admission requirements before making an enquiry.',tags:['Undergraduate','B.Sc.','B.Com.','BCA'],location:'Coimbatore',mode:'In person',price:'Ask for fee details',note:'Sample admission enquiry',color:'blue',details:'Fictional college profile for demonstrating admission discovery. Offers sample undergraduate programmes, a library and project-based learning. Confirm course eligibility and fees in a real admission enquiry.'};
listings.push(collegeExample);all.push(collegeExample);
function learnerGoals(){const f=record().fields;return [f.needs,f.secondNeed].filter(x=>x&&x!=='No second requirement')}
function matchingExamples(goal){if(goal==='School admission')return listings.filter(x=>x.id===4);if(goal==='College admission')return [collegeExample];if(goal==='Subject tuition')return listings.filter(x=>x.type==='Tuition');if(goal==='Skill development')return listings.filter(x=>x.type==='Skill development');if(goal==='NEET coaching')return listings.filter(x=>x.id===6);if(goal==='JEE coaching')return listings.filter(x=>x.id===2);return []}
function opportunitiesForRole(){const r=state.role,f=record().fields;
 if(r==='learner'){const goals=learnerGoals();return (goals.length?goals:['Subject tuition','School admission']).map((g,i)=>({name:g,why:goals.length?`${i===0?'Main':'Second'} requirement from your preferences`:'Example goal — customise your preferences',items:matchingExamples(g)}))}
 if(r==='teacher'){const p=selectedPurposes(),out=[];if(!p.length||hasPurpose('Find a job'))out.push({name:'Teaching jobs',why:p.length?'You selected job seeking':'Example opportunities — select your purpose',items:jobs});if(!p.length||hasPurpose('Offer tuition / coaching / training'))out.push({name:'Coaching & service opportunities',why:p.length?'You selected offering services':'Example opportunities — select your purpose',items:learnerNeeds});return out}
 if(r==='institution'){const p=selectedPurposes(),out=[];if(!p.length||hasPurpose('Hire teachers / professors'))out.push({name:'Teachers for your openings',why:'Explore skills against your hiring requirements',items:talents});if(hasPurpose('Training association / partnership'))out.push({name:'Training partners',why:'You selected a training association or partnership',items:listings.filter(x=>x.type==='Skill development')});return out}
 const p=selectedPurposes(),out=[];if(!p.length||hasPurpose('Individual learner enrolment'))out.push({name:'Individual learner opportunities',why:p.length?'You selected learner enrolment':'Example enquiries — select your purpose',items:learnerNeeds});if(!p.length||hasPurpose('Institutional partnerships'))out.push({name:'Institutional business opportunities',why:p.length?'You selected institutional partnerships':'Example briefs — select your purpose',items:business});return out;
}
function opportunitySection(section){return `<section class="opportunity-section"><div class="section-top"><div><h2>${esc(section.name)}</h2><p>${esc(section.why)} · Sample matches</p></div></div><div class="cards">${section.items.length?section.items.slice(0,3).map(card).join(''):'<div class="empty"><h3>No sample listing for this goal yet</h3><p class="muted">Your requirement is retained. Explore other options or refine your preferences.</p></div>'}</div></section>`}
function sponsorCandidate(){const r=state.role;if(r==='learner'){const g=learnerGoals();if(g.includes('College admission'))return {item:collegeExample,why:'Your college-admission preference',label:'Explore admission',action:'detail(7)'};if(g.includes('School admission'))return {item:listings.find(x=>x.id===4),why:'Your school-admission preference',label:'Explore admission',action:'detail(4)'};return null}if(r==='teacher'&&(!selectedPurposes().length||hasPurpose('Find a job')))return {item:jobs[0],why:'Your interest in teaching opportunities',label:'View role & apply',action:'detail(101)'};if(r==='institution'&&hasPurpose('Training association / partnership'))return {item:listings[2],why:'Your interest in institutional training',label:'Explore provider',action:'detail(3)'};return null}
function promotedHTML(){const p=sponsorCandidate();if(!p||discovery.dismissed.has(state.role+'-'+p.item.id))return '';return `<section class="promotion"><div class="promotion-body"><span class="sponsor-label">SPONSORED · SAMPLE PLACEMENT</span><h2>${p.item.name}</h2><p>${p.item.title}</p><span class="promotion-reason">Why this appears: ${p.why}. Sponsorship does not imply a better match.</span></div><div class="promotion-actions"><button class="btn" onclick="${p.action}">${p.label} ↗</button><button class="text-button" onclick="dismissPromotion(${p.item.id})">Hide this promotion</button></div></section>`}
function dismissPromotion(id){discovery.dismissed.add(state.role+'-'+id);workspace();toast('Promotion hidden for this session.')}
function guideHTML(){const p=skillPathways[discovery.focusSkill];return `<section class="skill-guide"><div class="guide-intro"><span class="eyebrow">AI SKILL GUIDE · DESIGN PREVIEW</span><h2>What could you learn next?</h2><p>Explore a skill, understand its value and choose a practical next step.</p><span class="guide-disclosure">Curated sample pathways. Live AI and current trend research are not connected.</span></div><div class="guide-body"><label for="future-skill">Explore a skill area</label><select id="future-skill" onchange="discovery.focusSkill=this.value;workspace()">${Object.keys(skillPathways).map(x=>`<option ${x===discovery.focusSkill?'selected':''}>${x}</option>`).join('')}</select><h3>${discovery.focusSkill}</h3><p class="muted">${p.why}</p><ol>${p.steps.map(s=>`<li>${s}</li>`).join('')}</ol><p class="bottom-note">${p.roles}. This is a starting point, not a job or admission guarantee.</p><div class="workspace-links"><button class="btn" onclick="addGuidedSkill()">Add to my learning goals</button><button class="btn outline" onclick="findGuidedTraining()">Explore sample training</button></div></div></section>`}
function addGuidedSkill(){const name=skillPathways[discovery.focusSkill].action;const r=record();if(!r.skills.some(s=>s.name===name&&s.purpose==='Want to learn'))r.skills.push({name,purpose:'Want to learn',level:'Beginner',priority:'Additional',years:'',custom:!catalog.includes(name)});r.complete=false;toast(name+' added as a learning goal.');workspace()}
function findGuidedTraining(){const key=skillPathways[discovery.focusSkill].action,items=listings.filter(i=>[i.title,i.desc,...i.tags].join(' ').toLowerCase().includes(key.toLowerCase()));modal(`<span class="eyebrow">SAMPLE LEARNING PATHWAY</span><h2>Explore ${esc(discovery.focusSkill)}</h2>${items.length?items.map(i=>`<div class="row"><div><strong>${i.name}</strong><p>${i.title}</p></div><button class="btn light" onclick="detail(${i.id})">View</button></div>`).join(''):'<p class="muted">No sample course is listed for this skill yet. Your learning goal can still be saved for future matching.</p>'}<p class="bottom-note">Real provider recommendations will use verified course data after integration.</p>`)}
function promotionDraft(){modal(`<span class="eyebrow">PROMOTION PLANNER · SAMPLE</span><h2>Reach people with a relevant need.</h2><p class="muted">Create a draft promotion. Nothing is published or sent.</p><form id="promotion-form"><div class="fields"><label class="full">Promotion title<input name="title" required maxlength="120"></label><label>Objective<select name="objective">${(state.role==='institution'?['Admission enquiries','Job applications','Training partnerships']:state.role==='teacher'?['Coaching enquiries','Workshop enquiries']:['Course enrolment enquiries','Institutional partnerships']).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Audience<select name="audience"><option>Adult learners / parents</option><option>Teachers / experts</option><option>Schools / colleges</option><option>Training providers</option></select></label><label class="full">Relevant skills, programmes or needs<input name="skills" required maxlength="300"></label><label class="full">Location / online reach<input name="location" required maxlength="100"></label></div><button class="btn">Save promotion draft</button></form><p class="bottom-note">Sponsored placements will be labelled. No direct child contact or automated promotional messages are enabled.</p>`);$('#promotion-form').onsubmit=e=>{e.preventDefault();discovery.campaigns.push({...Object.fromEntries(new FormData(e.target)),role:state.role});$('#modal').close();workspace();toast('Promotion draft saved for this session.')}}
function roleActions(){if(state.role==='learner')return `<button class="btn light" onclick="registration.step=steps().findIndex(s=>s.id==='preferences');navigate('profile')">Update both requirements →</button>`;if(state.role==='teacher')return `<button class="btn light" onclick="service()">Offer a service</button><button class="btn outline" onclick="promotionDraft()">Plan a promotion</button>`;if(state.role==='institution')return `<button class="btn light" onclick="startInstitutionPurpose('Hire teachers / professors')">Post an opening</button><button class="btn light" onclick="startInstitutionPurpose('Promote admissions')">Admission profile</button><button class="btn outline" onclick="promotionDraft()">Plan a promotion</button><button class="btn outline" onclick="startInstitutionPurpose('Training association / partnership')">Find training partners</button>`;return `<button class="btn light" onclick="providerAudience('learners')">Individual learners</button><button class="btn light" onclick="providerAudience('institutions')">Institutional opportunities</button><button class="btn outline" onclick="openProviderCourses()">Manage courses</button><button class="btn outline" onclick="promotionDraft()">Plan a promotion</button>`}
workspace=function(){const r=record(),sections=opportunitiesForRole(),skills=r.skills.map(x=>x.name),campaigns=discovery.campaigns.filter(x=>x.role===state.role);$('#main').innerHTML=intro('YOUR OPPORTUNITY DASHBOARD',{learner:'Learning today. Possibilities tomorrow.',teacher:'Let your skills open more doors.',institution:'Connect talent, admissions and growth.',training:'Turn expertise into opportunity.'}[state.role],'Your goals guide what appears here. All profiles and opportunities below are sample data.')+`<div class="dashboard-goals"><div><span class="tiny">YOUR PROFILE SIGNALS</span><div class="tags">${(state.role==='learner'?learnerGoals():selectedPurposes()).map(x=>`<span>${esc(x)}</span>`).join('')||'<span>No purposes selected yet</span>'}${skills.slice(0,5).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div><a class="btn outline" href="#profile">Refine my profile</a></div><div class="workspace-links dashboard-actions">${roleActions()}</div><div class="stats"><div class="stat"><b>${state.saved.size}</b><span>Shortlisted opportunities</span></div><div class="stat"><b>${state.enquiries.filter(x=>x.role===state.role).length+state.applications.filter(x=>x.role===state.role).length}</b><span>Demo enquiries / applications</span></div><div class="stat"><b>${r.skills.filter(x=>x.purpose==='Want to learn').length}</b><span>Skills to develop</span></div></div>${sections.map(opportunitySection).join('')}${promotedHTML()}${state.role==='institution'&&hasPurpose('Promote admissions')?'<section class="panel"><h2>Bring your admission programmes to the right families.</h2><p class="muted">Learners who select school or college admission can discover relevant institutions alongside their other learning goals.</p><button class="btn" onclick="promotionDraft()">Plan an admission promotion →</button></section>':''}${guideHTML()}<section class="panel"><h2>Manage your next steps</h2><div class="workspace-links" style="margin-top:20px"><a class="btn light" href="#saved">My shortlist</a><a class="btn light" href="#enquiries">Enquiries & applications</a><a class="btn outline" href="#profile">Profile & requirements</a><a class="btn outline" href="#plans">Membership</a></div></section>${campaigns.length?`<section class="panel"><h2>Your promotion drafts</h2>${campaigns.map(c=>`<div class="row"><div><strong>${esc(c.title)}</strong><p>${esc(c.objective)} · ${esc(c.audience)}<br>${esc(c.skills)}</p></div><span class="badge">Not published</span></div>`).join('')}</section>`:''}<p class="bottom-note">Recommendations in this preview use selected purposes and sample records, not live AI. Contact details are not sold; any future connection with a learner is managed by the adult learner or parent.</p>`;side('workspace')};
const profileBeforeOpportunity=profile;profile=function(){profileBeforeOpportunity();$('#main').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Your profile shapes your opportunities.</h2><p class="muted">${state.role==='learner'?'Your main and second requirements create separate learning and admission recommendations.':state.role==='teacher'?'Your job and service preferences guide vacancies, learner enquiries and professional development.':state.role==='institution'?'Your openings, admissions programmes and partnership goals guide talent and growth opportunities.':'Your course skills and expertise guide individual learner and institutional opportunities.'}</p><a class="btn light" href="#workspace">See my opportunity dashboard →</a></section>`)};
if(location.hash==='#workspace'||location.hash==='#profile')render();
const workspaceBeforeDrafts=workspace;workspace=function(){workspaceBeforeDrafts();const r=record(),drafts=[...state.requirements.filter(x=>x.role===state.role),...state.services.filter(x=>x.role===state.role),...(state.role==='institution'?r.openings:state.role==='training'?r.courses:[])];if(drafts.length)$('#main').insertAdjacentHTML('beforeend',`<section class="panel"><h2>Your requirements & listings</h2>${drafts.map(d=>`<div class="row"><div><strong>${esc(d.title)}</strong><p>${esc(d.budget||d.fee||d.salary||d.location||'Sample listing')}</p></div><span class="badge">Session draft</span></div>`).join('')}</section>`)};
